 return {'wins':sum(a['mean']<b['mean'] for a,b in ps),'n':len(ps),'sets':len({a['set_id'] for a,b in ps}),'ratio':round(float(np.median([a['mean']/b['mean'] for a,b in ps])),6),'margin':round(float(np.mean([b['mean']-a['mean'] for a,b in ps])),6),'budgets':dict(Counter(a['budget']['total_samples_seen'] for a,b in ps)),'datasets':len({a['dataset_id'] for a,b in ps})}
