  c=dict(letter=let,d=get(r'd_model: (\d+)'),n=get(r'num_layers: (\d+)'),heads=get(r'num_heads: (\d+)'),ff=get(r'd_ff: (\d+)'),opt=get(r'Optimizer: (\w+)'),lr=get(r'Learning rate: ([\de.-]+)'),wd=get(r'Weight decay: ([\de.-]+)'))
