def parse(r):
 out=[]
 for letter,s in re.findall(r'### Choice ([A-E])\s*(.*?)(?=### Choice |## Your answer|\Z)',r['question'],re.S):
  def get(p):
   m=re.search(p,s);return m.group(1) if m else None
  o=get(r'- Optimizer: (\w+)');lr=get(r'- Learning rate: ([\deE.+-]+)');ln=get(r'- Layer norm per layer: (\[[^\]]+\])');act=get(r'- Activation: (\w+)');mom=get(r'- Momentum: ([\d.]+)')
  if o and lr:out.append(dict(letter=letter,opt=o,lr=float(lr),ln=ln.count('True') if ln else 0,act=act,mom=float(mom) if mom else 0))
 return out
for rival in ['Adagrad','SGD']:
 n=hit=unknown=0;ids=[]
 for r in h:
  if r['family']!='univariate_regression':continue
  cs=parse(r);order=re.findall(r'[A-E]',r['answer'])
  for a in cs:
   if a['opt']!='RMSprop' or a['lr']>.0001 or a['ln']<1:continue
   for b in cs:
    ok=(b['opt']=='Adagrad' and b['lr']>=.001) if rival=='Adagrad' else (b['opt']=='SGD' and b['mom']==.9 and b['lr']<=.001)
    if not ok:continue
    if a['letter'] not in order or b['letter'] not in order:unknown+=1;continue
    n+=1;win=order.index(a['letter'])<order.index(b['letter']);hit+=win;ids.append((r['question_id'],a['letter'],b['letter'],win))
 print(rival,'checked',n,'hits',hit,'misses',n-hit,'unknown',unknown,'records',ids)
"}

