  lines=re.findall(r'^- (.*)',p,re.M); opts=[x for x in lines if x.startswith(('Optimizer:','Learning rate:','Weight decay:','Betas:','Momentum:'))]; model=[x for x in lines if not x.startswith(('Optimizer:','Learning rate:','Weight decay:','Betas:','Momentum:','Loss:'))]
  def val(name):return next((x.split(': ',1)[1] for x in opts if x.startswith(name+':')),None)
  if val('Learning rate'):cs.append((p[0],model,opts,float(val('Learning rate')),val('Optimizer')))
 for a,b in itertools.combinations(cs,2):
  if a[1]!=b[1] or a[4]!=b[4] or a[3]==b[3]:continue
  lo,hi=sorted([a,b],key=lambda c:c[3]); ans=r['answer']
  if '<' in ans:win=ans.index(hi[0])<ans.index(lo[0])
  elif ans in [lo[0],hi[0]]:win=ans==hi[0]
  else:continue
  out.append({'qid':r['question_id'],'epoch':r['epoch'],'family':r['family'],'lo':lo[0],'hi':hi[0],'high_wins':win,'config_equal_except_lr':[x for x in lo[2] if not x.startswith('Learning rate:')]==[x for x in hi[2] if not x.startswith('Learning rate:')]})
