for r in l:
 if r.get('excluded') or r.get('failed_seeds') or not np.isfinite(r['mean']):continue
 g[json.dumps([r['set_id'],r['model'],r['loss'],r['budget']],sort_keys=True)].append(r)
def delta(r):
 o=r['optimizer'];t=r['budget']['training_steps'];lr=o['lr']
 if o['type']=='Adagrad':return 2*lr*np.sqrt(t)
 if o['type']=='SGD':return lr*t*(.003 if r['family']=='bigram_lm' else .03 if 'regression' in r['family'] and o.get('momentum',0) else .01)/(1-o.get('momentum',0))
 return lr*t
ps=[]
