 for a,b in itertools.combinations(rs,2):
  if delta(a)>delta(b):a,b=b,a
  if delta(b)<3*delta(a) or delta(a)==delta(b):continue
  ps.append({'family':a['family'],'set':a['set_id'],'low_id':a['candidate_id'],'high_id':b['candidate_id'],'width':a.get('width',a.get('d_model')),'depth':a.get('depth',a.get('num_layers')),'steps':a['budget']['training_steps'],'batch':a['budget']['batch_size'],'rule':a['dataset'].get('rule_family'),'low_delta':float(delta(a)),'high_delta':float(delta(b)),'low_opt':a['optimizer'],'high_opt':b['optimizer'],'ratio':b['mean']/a['mean'],'high_wins':b['mean']<a['mean']})
with open('displacement_audit/proxy_pairs.json','w') as f:json.dump(ps,f)
for fam in sorted(set(p['family'] for p in ps)):
 pp=[p for p in ps if p['family']==fam];print(fam,'higher proxy wins',sum(p['high_wins'] for p in pp),'/',len(pp),'sets',len(set(p['set'] for p in pp)),'median ratio',round(float(np.median([p['ratio'] for p in pp])),3))
print('same architecture but optimizer/decay/betas confounded; >=3x proxy gap')
"}

